import unittest
from candidate import incr_list


class TestIncrList(unittest.TestCase):
    def test_incr_list_positive_integers(self):
        self.assertEqual(incr_list([1, 2, 3]), [2, 3, 4])

    def test_incr_list_negative_integers(self):
        self.assertEqual(incr_list([-3, -2, -1]), [-2, -1, 0])

    def test_incr_list_mixed_positive_negative(self):
        self.assertEqual(incr_list([-5, 0, 5]), [-4, 1, 6])

    def test_incr_list_single_element(self):
        self.assertEqual(incr_list([42]), [43])

    def test_incr_list_empty_list(self):
        self.assertEqual(incr_list([]), [])

    def test_incr_list_floats(self):
        self.assertEqual(incr_list([1.5, 2.5, 3.5]), [2.5, 3.5, 4.5])

    def test_incr_list_mixed_int_and_float(self):
        self.assertEqual(incr_list([1, 2.5, 3]), [2, 3.5, 4])

    def test_incr_list_large_numbers(self):
        self.assertEqual(incr_list([10**18, 2**60]), [10**18 + 1, 2**60 + 1])

    def test_incr_list_zero(self):
        self.assertEqual(incr_list([0]), [1])

    def test_incr_list_multiple_zeros(self):
        self.assertEqual(incr_list([0, 0, 0]), [1, 1, 1])

    def test_incr_list_does_not_modify_original(self):
        original = [1, 2, 3]
        result = incr_list(original)
        self.assertEqual(original, [1, 2, 3])
        self.assertIsNot(result, original)

    def test_incr_list_return_type_is_list(self):
        result = incr_list([1, 2, 3])
        self.assertIsInstance(result, list)

    def test_incr_list_with_none_element_raises_type_error(self):
        with self.assertRaises(TypeError):
            incr_list([1, None, 3])

    def test_incr_list_with_string_element_raises_type_error(self):
        with self.assertRaises(TypeError):
            incr_list(["a", 2, 3])

    def test_incr_list_with_none_as_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            incr_list(None)

    def test_incr_list_with_bool_values(self):
        self.assertEqual(incr_list([True, False]), [2, 1])

    def test_incr_list_with_nested_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            incr_list([[1, 2], 3])

    def test_incr_list_preserves_order(self):
        self.assertEqual(incr_list([5, 1, 4, 2, 3]), [6, 2, 5, 3, 4])

    def test_incr_list_duplicate_elements(self):
        self.assertEqual(incr_list([7, 7, 7]), [8, 8, 8])


if __name__ == '__main__':
    unittest.main()
